<template>
  <div>
    <artiste-header :navLinks="navLinks"></artiste-header>
    <div id="home-section" class="upper-clear-area">
    </div>
    <div class="white-area">
      <div class="ui eight column grid">
        <div class="column"></div>
        <div class="column title-area">
          <h1 class="title-left">{{title}}</h1>
        </div>
        <div class="eight wide column">
          <p class="title-right">{{description}}</p>
        </div>
      </div>
    </div>
    <div class="art-area">
      <div id="portraits-section">
        <art-thumbnail-list :title="portraits.title" :color="portraits.color" :arts="portraits.arts">
        </art-thumbnail-list>
      </div>
      <div id="scenarios-section">
        <art-thumbnail-list :title="scenarios.title" :color="scenarios.color" :arts="scenarios.arts">
        </art-thumbnail-list>
      </div>
      <div id="designs-section">
        <art-thumbnail-list :title="designs.title" :color="designs.color" :arts="designs.arts">
        </art-thumbnail-list>
      </div>
      <div id="cartoons-section">
        <art-thumbnail-list :title="cartoons.title" :color="cartoons.color" :arts="cartoons.arts">
        </art-thumbnail-list>
      </div>
    </div>
  </div>
</template>

<script>
import ArtisteHeader from './ArtisteHeader.vue'
import ArtThumbnailList from './ArtThumbnailList'
import axios from 'axios'

export default {
  name: 'Home',
  data () {
    return {
      title: 'Art |',
      description: 'Art is the conscious creation of something beautiful or meaningful using skill and imagination.',
      portraits: {title: 'Portraits', color: 'blue', arts: []},
      scenarios: {title: 'Scenarios', color: 'green', arts: []},
      designs: {title: 'Designs', color: 'yellow', arts: []},
      cartoons: {title: 'Cartoons', color: 'orange', arts: []},
      navLinks: []
    }
  },
  created () {
    axios.get('/static/store.config.json')
      .then(response => {
        response.data.navLinks.forEach(l => this.navLinks.push(l))
      })
      .catch(e => {
        console.error(e)
      })
    axios.get('/static/store.index.json')
      .then(response => {
        response.data.portraits.forEach(p => this.portraits.arts.push(p))
        response.data.scenarios.forEach(s => this.scenarios.arts.push(s))
        response.data.designs.forEach(d => this.designs.arts.push(d))
        response.data.cartoons.forEach(c => this.cartoons.arts.push(c))
      })
      .catch(e => {
        console.error(e)
      })
  },
  components: {
    ArtisteHeader,
    ArtThumbnailList
  }
}
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style scoped>
  .upper-clear-area {
    height: 78vh;
    width: 100%;
  }
  .white-area {
    color: white;
    background-color:rgba(0,0,0,0.5);
    height: 150px
  }
  .title-area {
    padding-top: 30px;
    padding-bottom: 30px;
  }
  .title-left {
    font-size: 56px;
    padding-top: 15px;
  }
  .title-right {
    font-size: 24px;
    padding-top: 20px
  }
  .art-area {
    width: 100%;
    background-color: rgba(255,255,255,0.9);
    padding-bottom: 200px;
  }
</style>



