<template>
  <div class="column">
    <div class="card">
      <div class="image">
        <img :src="art.file">
      </div>
      <div class="content">
        <div class="header">{{art.title}}</div>
        <div class="description">{{art.description}}</div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'ArtThumbnail',
  data () {
    return {

    }
  },
  props: {
    art: Object
  }
}
</script>

<style scoped>
  img {
    width: 100%; height: auto;
  }
  .card {
    padding: 20px;
  }
</style>



