<template>
  <div class="ui four column container grid" v-if="isThumbnailsAvailable()">
    <div class="row">
      <div class="eleven wide column">
        <a class="ui ribbon label" :class="[color]">{{title}}</a>
      </div>
    </div>
    <div class="row">
      <art-thumbnail v-for="(art, index) in arts" :art="art" :key="index"></art-thumbnail>
    </div>
  </div>
</template>

<script>
import ArtThumbnail from './ArtThumbnail.vue'
export default {
  name: 'ArtThumbnailList',
  data () {
    return {

    }
  },
  props: {
    title: String,
    color: String,
    arts: Array
  },
  methods: {
    isThumbnailsAvailable: function () {
      return this.arts.length > 0
    }
  },
  components: {
    ArtThumbnail
  }
}
</script>

<style scoped>
  .grid {
    padding-top: 90px;
    padding-left: 100px;
    padding-right: 100px;
  }

  .row {
    padding-bottom: 50px;
  }

  .label {
    font-size: 20px;
  }
</style>



